readonly class Money {
    public function __construct(public float $amount, public string $currency) {}
    public function withAmount(float $a): static { return new static($a, $this->currency); }
}
// == compares values, === compares identity

public record Money(decimal Amount, string Currency);

var price = new Money(10, "USD");
var cheaper = price with { Amount = 8 };
Console.WriteLine(price == new Money(10, "USD")); // True (value equality)

