var a = new Money(10m, "USD");
var b = new Money(10m, "USD");

Console.WriteLine(a == b);
Console.WriteLine(ReferenceEquals(a, b));
Console.WriteLine(a);

var c = a with { Amount = 25m };
Console.WriteLine(a.Amount);

var (amount, currency) = c;
Console.WriteLine($"{amount} {currency}");

public record Money(decimal Amount, string Currency)
{
    public Money Add(Money other) => this with { Amount = Amount + other.Amount };
}

object[] things = { 42, "hello", new Money(5m, "USD"), new Money(500m, "EUR"), null! };

foreach (var thing in things)
    Console.WriteLine(Describe(thing));

static string Describe(object? value) => value switch
{
    null => "nothing",
    int n when n > 40 => $"a big number: {n}",
    int n => $"a number: {n}",
    string { Length: 0 } => "an empty string",
    string s => $"text of length {s.Length}",
    Money { Amount: >= 100 } m => $"a lot of money: {m}",
    Money m => $"some money: {m.Amount} {m.Currency}",
    _ => "something else",
};

static decimal Shipping(decimal total) => total switch
{
    < 50 => 5m,
    < 100 => 2.5m,
    _ => 0m,
};

Console.WriteLine(Shipping(75));

